//プラグイン名　（★絶対変更する）
name,バーチャル道頓堀
//インストールディレクトリ名　（★絶対変更する）
directory,TOMBORI

ほか

- yaya.txtのiolog, offをコメントアウトしログ出力オンにすると、プラグインにどんなイベントが発生するのか把握可能（yaya.txtデフォルト設定ではOnSecondChangeは無視）ゴーストと同じように発生するイベントとしないイベントがあり。
- 里々から\![raiseplugin]で値を送るとき「、」や「。」に自動的にウェイトタグが付く場合があり（「φ。」と書いても防げない）
- プラグインエクスプローラーを開き、プラグイン無効→有効でプラグインリロード

参考サイト

- プラグイン仕様書

テキストの幅を揃える

> AYAYA Wiki より転載

等幅フォントで使用してください。<br>
指定したバイト数をオーバーすればその分テキストを削ります。<br>
指定したバイト数まで足りない場合は余ったスペースを空白で埋めます。<br>

使い方

第一引数(_argv[0])　文字列<br>
第二引数(_argv[1])　揃えるバイト数<br>

ARRANGETEXT(文字列,揃えるバイト数)

ARRANGETEXT関数

 ARRANGETEXT
 {
 _sb=TOINT(_argv[1])
 _bytes=(GETSTRBYTES(_argv[0],0))
	if _bytes < _sb {
	// 半角空白で埋める
	_space=(_sb-_bytes)
	_val=_argv[0]
	_lp=1
		while _lp <= _space {
		_val=_val+' '
		_lp++
		}
	_val
	}
	elseif _bytes > _sb {
	// 越えていれば削る
	_leng=_sb
	_loop=0
	_text=_argv[0]
	_byte=0
	_c=''
		while _byte<_leng {
			_sub=(SUBSTR((_text),(_loop),1))
			_c=_c+_sub
			_byte=(GETSTRBYTES(_c,0))
			_loop++
				if _loop>200 {break}
		}
	_re=RE_GREP(_c,'.$')
	_re=RE_GETSTR
			if (GETSTRBYTES((_c),0))>_leng {
				_c=(RE_REPLACE(_c,'.$',''))+' '
				_c
			}
			else {_c}
	}
	else {_argv[0]}
 }

見切れ・重なり反応を里々風に

> AYAYA Wiki より転載

里々では、見切れ・重なり状態になっても多少の間を空けてから見切れ・重なりイベントが発生するようです。<br>
で、その方が動作としては自然っぽいので、文でやる方法を。

フラグ使いまくりなのであまり綺麗じゃありませんが。

OnSecondChange
{
    if mikireenable && reference1 && !mikireflag {
       mikiretimer--;
       if mikiretimer < 1 {
          mikireflag   = 1
          "" //見切れ反応時のトーク
       }
    } else {
       mikiretimer = 5
    }

    if mikireflag && !reference1 {
       //5秒以内に復帰した場合は、見切れ後トークを行わない
       endmikire = 1
    }

    if endmikire {
       "" //見切れ終了時のトーク
    }

    if kasanarienable && reference2 {
       kasanaritimer--;
       if kasanaritimer < 1 {
          kasanarienable = 0;
          "" //重なり反応時のトーク
          kasanarienable = 1;
       }
    } else {
       kasanaritimer = 5
    }
}

--せきやひろし

別解書いてみました。<br>
上のサンプルが動作しない場合はこちらを。<br>
（reference*をreference[*]と書いています）

OnSecondChange
{
　　//見切れ反応（メインキャラ見切れ5秒後）
　　if reference[1] && !mikireflag {
　　　　mikiretimer--
　　　　if mikiretimer < 1 {
　　　　　　mikireflag = 1
　　　　　　"" //見切れ反応時のトーク
　　　　}
　　}
　　else {
　　　　mikiretimer = 5
　　}

　　//見切れ終了反応（見切れ終了直後）
　　if mikireflag && !reference[1] {
　　　　mikireflag = 0
　　　　"" //見切れ終了時のトーク
　　}

　　//重なり反応（メインとサブキャラの重なり5秒後）
　　elseif !kasanariflag && reference[2] {

　　　　if ISVAR('kasanaritimer') == 0 {
　　　　　　kasanaritimer = 5
　　　　}

　　　　kasanaritimer--
　　　　if kasanaritimer < 1 {
　　　　　　kasanariflag = 1
　　　　　　"" //重なり反応時のトーク
　　　　}
　　}
　　//重なり終了反応（重なり終了直後）
　　elseif kasanariflag && !reference[2] {
　　　　kasanariflag = 0
　　　　kasanaritimer = 5
　　　　"" //重なり反応終了時のトーク
　　}
　　else {
　　　　kasanaritimer = 5
　　}
}

複雑な _in_ チェック

> AYAYA Wiki より転載

ゴーストのトーク判定など、文字列に何かが含まれているかどうかを
複雑な条件で判定するときに。

（文責：浮子屋）

//*****************************************************************************
//	InStrCheck
//	対象文字列の中にチェック文字列が含まれているかどうかを
//	複雑な条件によって判定する
//	argv0:		チェック対象文字列
//	argv1以降:	チェック文字列
//	
//	result:0（チェック失敗）または1（チェック合格）
//	
//	・argv1以降の引数はAND条件となる。
//	・チェック文字列は | で分割可能。この場合はOR条件となる。
//	・チェック文字列の先頭が ! の場合、含まれる、含まれないの判定が逆になる
//	・上記逆転は分割後に評価される
//
//	（例）
//		"hogehemo","hoge","hemo"
//		hogehemo の中に hoge が含まれ AND hemo が含まれるかどうか:結果は1
//		
//		"hogehemo","!hoge","hemo"
//		hogehemo の中に hoge が含まれず AND hemo が含まれるかどうか:結果は0
//		
//		"hogehemo","hoge|pepe"
//		hogehemo の中に hoge が含まれ OR pepe が含まれるかどうか:結果は1
//
//		"hogehemo","hoge|!pepe","!humu"
//		hogehemo の中に hoge が含まれ OR pepe が含まれず、
//		かつ humu が含まれないかどうか:結果は1
//
//		
//*****************************************************************************
InStrCheck
{
	for _i=1 ; _i<_argc ; _i++ {
		_words=SPLIT(_argv[_i],'|')
		_isHit=0
		foreach _words ; _word{
			_onHit=1
			if SUBSTR(_word,0,1) == '!' {
				_word=SUBSTR(_word,1,STRLEN(_word)-1)
				_onHit=0
			}
			if _word _in_ _argv[0] {
				_isHit=_isHit || _onHit
			}else{
				_isHit=_isHit || (1-_onHit)
			}
		}
		if ! _isHit {
			0
			return
		}
	}
	1
	return
}

中身の残っているディレクトリを削除する

> AYAYA Wiki より転載

中身の残っているディレクトリを削除する方法

AYA/YAYAに標準で用意されているディレクトリ削除関数、RMDIRでは空のディレクトリしか削除できません。<br>
なので、中身が残っていても削除が可能な関数を作ってみました(deltreeコマンドのようなもの)。

なお、この関数では読み取り専用のファイルやディレクトリなども強制的に削除されます。<br>
また、Windowsの削除コマンドを使っているわけではないので、削除したファイルやディレクトリがゴミ箱など、一時的なディレクトリに入ると言うこともありません。<br>
したがって、ディレクトリ指定を間違うと、場合によっては取り返しが付かない事態になることがありますので、使用する場合は十分ご注意ください。

使い方

DELTREE(削除したいディレクトリ・ファイル名)

DELTREE関数

//ディレクトリ削除関数(再帰あり)
DELTREE
{
	_dirname = _argv[0];	//引数を分かりやすい名前の変数に代入

	_attr_array = FATTRIB(_dirname);	//ファイル属性を取得

	if (_attr_array == -1 ){
		-1;	//ファイルが存在しない、などの場合は-1を返して終了
		return;
	} elseif (_attr_array[2]==1) {
		//対象がディレクトリなら、ディレクトリ削除処理実行
		while 1 {	//無限ループ(ディレクトリを確実に消去するため)
			//ディレクトリ内ファイル・ディレクトリ一覧取得
			_files = FENUM(_dirname,'|');		//┐
			_files = REPLACE(_files,'\','/');	//├ここのスプリッタは必要に応じて変更
			_file_array = SPLIT(_files,'|');	//┘

			if (ARRAYSIZE(_file_array) == 0) {
				//ディレクトリ内に何もなければディレクトリ削除実行。
				//RMDIR関数を実行し、その結果をそのまま返す。
				RMDIR(_dirname);
				return;
			} else {
				//取得した一覧を元にファイル・ディレクトリ削除実行
				foreach _file_array; _filename {
					//処理すべきファイル・ディレクトリ名を生成
					_targetfilename = "%(_dirname)/%(_filename)";
					void DELTREE(_targetfilename);	//再帰呼び出し
				}
			}
		}
	} elseif (_attr_array[2]==0){
		//普通のファイルなら単純に削除。FDEL関数の結果をそのまま返す。
		FDEL(_dirname);
		return;
	} else {
		//その他、状況が不明な場合は0を返して終了
		0;
		return;
	}
}

- せきやひろし

使用しているソフトを判別

> AYAYA Wiki より転載

使用しているソフト（ベースウェア）を判別します。

BwName
{
